"""Serialize the individually authored stock-position design, not generic questions."""
import json
import re
from pathlib import Path

RUN = Path(__file__).resolve().parent

def refs(*numbers):
    return [f'SRC-{n:03d}' for n in numbers]

def build():
    source_rows = [
        ('Inventory on-hand list','Microsoft','https://learn.microsoft.com/en-us/dynamics365/supply-chain/inventory/inventory-on-hand-list','Public page inspected 2026-09-09; revision pin pending','Selected indexed text: dimensions, aggregation and hierarchy reservations; vendor-specific practice.'),
        ('Reserve inventory quantities','Microsoft','https://learn.microsoft.com/en-us/dynamics365/supply-chain/inventory/reserve-inventory-quantities','Public page inspected 2026-09-09; revision pin pending','Selected indexed text: physical and expected-receipt reservations are distinct.'),
        ('Stock report','Odoo','https://www.odoo.com/documentation/18.0/applications/inventory_and_mrp/inventory/warehouses_storage/reporting/stock.html','Odoo 18.0','Indexed passage only; direct open timed out. Distinct stock, usable and planned measures.'),
        ('Consignment','Odoo','https://www.odoo.com/documentation/18.0/applications/inventory_and_mrp/inventory/shipping_receiving/daily_operations/owned_stock.html','Odoo 18.0','Indexed article: owner versus custodian and stock reporting; not legal title advice.'),
        ('Inventory adjustments','Odoo','https://www.odoo.com/documentation/18.0/applications/inventory_and_mrp/inventory/warehouses_storage/inventory_management/count_products.html','Odoo 18.0','Indexed article: count, application, intervening movements, negative balance and reversal.'),
        ('EPCIS Standard','GS1','https://ref.gs1.org/standards/epcis/2.0.1/','URL 2.0.1; retrieved PDF header Release 2.0 June 2022','Selected sections 7.3.3.1 and 7.4.1: quantity and time constraints, not a stock balance engine.'),
        ('Inventory Visibility public APIs','Microsoft','https://learn.microsoft.com/en-us/dynamics365/supply-chain/inventory/inventory-visibility-api','2026-03-10','Selected query contracts: source-qualified measures, dimensions and returnNegative; no idempotency claim verified.'),
        ('Inventory Visibility reservations','Microsoft','https://learn.microsoft.com/en-us/dynamics365/supply-chain/inventory/inventory-visibility-reservations','Public page inspected 2026-09-09; revision pin pending','Selected indexed mapping/formula text: soft reservation and offsets require configured semantics.'),
        ('PROV-DM','W3C','https://www.w3.org/TR/prov-dm/','Recommendation 2013-04-30','Attribution and derivation alignment; no inventory authority or correctness inferred.'),
        ('Date and Time on the Internet: Timestamps','IETF','https://www.rfc-editor.org/rfc/rfc3339','RFC 3339 July 2002','Seconds and explicit offset; time is not identity, total ordering or snapshot consistency.'),
    ]
    sources=[dict(id=f'SRC-{i:03d}',title=t,organization=o,url=u,version_or_date=v,source_type='standard' if i in (6,9,10) else 'first-party-doc',primary_source=True,authority_tier=1 if i in (6,9,10) else 2,accessed_at='2026-09-09T19:25:00Z',relevance=r) for i,(t,o,u,v,r) in enumerate(source_rows,1)]
    design=(RUN/'question-design.md').read_text(encoding='utf-8')
    bundle_sections=re.split(r'(?m)^## ',design)[1:]
    ids=['position-grain','custody-location','quantity-basis','stock-restrictions','reservation-availability','projected-stock','snapshot-currency','count-adjustment','balance-lineage','action-boundary','stock-governance','stock-exchange']
    kinds=[['identity','composition','quality'],['ownership','spatial','authority'],['measurement','evidence','exception'],['classification','constraint','state'],['relationship','measurement','authority'],['event','measurement','lifecycle'],['temporal','quality','provenance'],['evidence','validation','decision'],['provenance','exception','validation'],['authority','requirement','exception'],['ownership','access','retention'],['interoperability','constraint','validation']]
    bundles=[]
    ordinal=0
    for bundle_section in bundle_sections:
        name=bundle_section.split('\n',1)[0]
        layers=[]
        for section in re.split(r'(?m)^### ',bundle_section)[1:]:
            heading,body=section.split('\n',1)
            qtext,fields=body.split('Candidate fields:',1)
            questions=re.findall(r'(?m)^- (.+\?)$',qtext)
            groups=re.findall(r'([a-z][a-z-]*)\s*\{([^}]+)\}',fields.split('Sources:',1)[0])
            sr=re.findall(r'SRC-\d{3}',fields.split('Sources:',1)[1])
            assert len(questions)==len(groups)==3
            lid=ids[ordinal]
            elements=[dict(id=lid+'-'+key,name=key,description='Proposed structured answer group: '+description+'. Explicit unknowns are allowed; nested executable schema remains deferred.',value_kind='object',cardinality='1',required=True,source_refs=sr) for key,description in groups]
            description='Time-qualified stock-position assertions for '+heading.lower()+', with declared source semantics and master authority.'
            finding=dict(id=lid+'-record',name=heading+' record',description=description,source_refs=sr,questions=[dict(id=lid+f'-q{i+1:02d}',text=q,kind=kinds[ordinal][i],answer_data=[elements[i]['id']]) for i,q in enumerate(questions)],data_elements=elements,artifacts=[dict(id=lid+'-evidence',name=heading+' evidence',description='Scoped snapshot, mapping or master receipt evidence for '+heading.lower()+'. Do not copy protected transaction payloads without permission.',media_or_form=['application/json','application/yaml','text/markdown','external reference'],serial=True,identity_strategy='Master-system ID first, then issuer-qualified UUID; immutable revision and exact-byte digest separately. Timestamp alone is not an identifier.',source_refs=sr)],inline_only_rationale=None)
            layers.append(dict(id=lid,name=heading,description=description,source_refs=sr,findings=[finding]))
            ordinal+=1
        assert len(layers)==2
        bundles.append(dict(id='stock-'+re.sub('[^a-z]+','-',name.lower()).strip('-'),name=name,description='Stock-position concerns: '+name.lower()+'.',rationale='Groups two subject-specific records while keeping stock quantities separate from goods and movement masters.',source_refs=sorted(set(s for layer in layers for s in layer['source_refs'])),layers=layers))
    assert len(bundles)==6 and ordinal==12
    model=dict(registry_id='vr.wm-obj-020',model_id='WM-OBJ-020',name='Inventory Stock Position',entry_kind='aggregate',purpose='Describe a source-qualified inventory quantity position by product, ownership, location, status and time.',scope_statement='The aggregate owns stock-position identity, declared dimension grain, measured and derived quantities, snapshot currency, reconciliation evidence and bounded operational references. It is informational, not a physical object or execution engine.',in_scope=['Stock dimension tuple, custody, restrictions and quantity basis','Reservation and planned-measure semantics with source-defined formulas','Snapshot consistency, count reconciliation, lineage and governed exchange'],out_of_scope=['Physical product geometry or material remastered as properties of a balance','Inventory booking engine, automatic warehouse actuation and oversell guarantees','Legal title determination, financial valuation and accounting entries'],boundary_notes=[dict(neighbor=n,distinction=d,source_refs=s) for n,d,s in [('WM-OBJ-001 Physical Item','REFERENCE only: a stock aggregate is not a serial item or its physical characteristics.',refs(1,5)),('WM-OBJ-002 Product Type / Catalog Item','Product identity and unit conversion master stay referenced, not copied.',refs(1,3)),('WM-FLW-012 Inventory Movement','Movement changes positions but is not itself the current balance; no complete event ledger is assumed.',refs(1,5,6)),('Reservation, order, warehouse and valuation masters','Position retains qualified references and quantities; execution, facility identity and monetary valuation remain external.',refs(2,4,7,8))]])
    services=dict(
        dimension=dict(owner_package_requirements=['Declare the Dimension owner and delegated inventory steward.','Register authoritative stock, product, movement and location namespaces.','Bind actual read, export, action and retention policies before operation.'],namespace_guidance='Issuer-qualified position ID plus explicit dimension tuple and immutable snapshot ID; neither product code nor timestamp alone identifies the position.',registry_links=['Model registry','Stock source registry','Product and location registries','Movement and action receipt registries']),
        canon_and_patch=dict(canonicalization_rules=['Preserve grain, unit, bucket semantics, effective time and unknown values.','Never add overlapping status buckets or hierarchy reservations without a declared aggregation rule.'],patch_rules=['Authorized namespaced schema extension with pinned base digest; reject incompatible unit or grain changes.','Corrections append successor snapshots and reasons; stale-base edits do not overwrite a master.'],compatibility_rules=['A changed bucket meaning or dimension grain needs explicit migration and new schema revision.','Lossy exchange cannot silently replace authoritative stock data.']),
        artifact_rules=dict(identity_priority=['Authoritative master-system identifier','Governed issuer-qualified URI or global identifier','Dimension-issued UUID with issuer context'],timestamp_rule='RFC 3339 timestamps with seconds and explicit offset or Z; distinguish effective, recorded and counted times. Timestamps are not collision-proof identity.',serial_naming_rule='Artifact-kind prefix plus stable escaped identifier and revision; timestamp may be appended for readability, not uniqueness.',integrity_rule='Preserve exact-byte digest, source receipt and mapping version; a digest proves byte identity, not stock truth.'),
        policies=['Availability formulas and allowed negative values must be declared by measure and source.','Count evidence does not authorize inventory adjustments or legal ownership changes.','On missing access, incomplete snapshot or stale evidence preserve unknowns; do not infer zero.','Do not retry uncertain operational actions until the authoritative receipt and idempotency capabilities have been checked.'],
        crud=dict(read=['Read owner policy, pinned specification, source grain, snapshot currency and access scope before using quantities.'],create=['Create a qualified snapshot from authorized source evidence; retain unobserved and excluded dimensions explicitly.'],update=['Append corrected snapshots with expected-base checks and provenance; route operational actions to the authorized master and verify its receipt.'],delete=['Apply retention and legal-hold policies; tombstone local records with protected provenance, never cascade deletion into product, movement or organization masters.']),
        roles=[dict(name=n,responsibilities=[r]) for n,r in [('Dimension owner','Defines namespaces and federation policy.'),('Inventory steward','Owns stock measure semantics and source bindings.'),('Count observer','Records evidence without assuming adjustment approval.'),('Adjustment approver','Authorizes a scoped master change under policy.'),('Reviewer','Checks aggregation, reconciliation and mappings.'),('Custodian','Maintains authorized caches and evidence retention.')]],
        access=dict(default_rule='Deny unless the owning Dimension explicitly authorizes the scope and purpose.',scopes=['bundle','layer','finding','artifact'],exceptions=['Only recorded scoped and time-limited delegation; no stock custody implies unrestricted disclosure.'],audit_requirements=['Record actor, purpose, source snapshot, action decision and receipt without secrets.']),
        agents_bootstrap=dict(filename='AGENTS.md',required_fields=['Name','Type','Specification URL','Storage type URL','Interface URL','Processes URL'],read_order=['Dimension owner and policy','Pinned stock model and source-grain bindings','Authorized snapshot and freshness rules','Dependencies, validation, extensions, action boundaries and retirement']))
    fnrows=[
        ('read-position','Read a qualified stock position','Retrieve stock for one declared dimension grain.',['Authorized source query','Desired dimensions'],['Snapshot or explicit incomplete/unknown outcome'],['Read permission and source contract'],['No cross-owner aggregation or missing row interpreted as zero'],refs(1,7)),
        ('qualify-availability','Explain availability','Trace source-defined availability formulas without executing reservations.',['Stock measures','Formula and offset mappings'],['Qualified availability and unresolved inputs'],['Compatible grain, units and source time'],['No universal subtraction or physical-stock inference from future reservations'],refs(1,2,8)),
        ('project-stock','Describe projected stock','Keep planning-horizon estimates distinct from observed balances.',['Current snapshot','Referenced planned receipts and issues'],['Scenario-qualified projection'],['Declared plan version and fulfillment status'],['No delivery promise or transaction authority granted'],refs(3,7)),
        ('reconcile-count','Reconcile count evidence','Compare a count and intervening movement evidence before proposing an adjustment.',['Count record','Source snapshots and movement references'],['Explained difference or unresolved discrepancy'],['Matched owner, grain, unit and time'],['No booking from count alone; approval remains external'],refs(5,9)),
        ('route-stock-action','Route an authorized action','Describe a master-mediated reservation or adjustment with explicit uncertain outcomes.',['Authorized request','Expected state and master capability declaration'],['Master receipt or uncertain/rejected outcome'],['Actual delegated authority and verified endpoint contract'],['No local property edit masquerades as execution; no blind retry after lost response'],refs(7,8)),
        ('exchange-position','Exchange with semantic loss report','Map authorized stock knowledge while preserving incompatible target constraints.',['Source snapshot','Pinned target mapping'],['Projection and loss/rejection report'],['Source disclosure allowed and target constraints checked'],['Reject unqualified signed stock to positive-only event quantity mapping'],refs(6,7,9)),
    ]
    functions=[dict(id=i,name=n,description=d,inputs=a,outputs=b,preconditions=c,effects=e,source_refs=s) for i,n,d,a,b,c,e,s in fnrows]
    composition=[dict(target=t,relation=r,purpose=p,required=req,source_refs=s) for t,r,p,req,s in [('WM-OBJ-001','REFERENCE','Link identifiable physical items only when item-level evidence exists; aggregate remains nonphysical.',False,refs(1,5)),('WM-OBJ-002','REFERENCE','Resolve product identity and qualified unit basis.',True,refs(1,3)),('WM-FLW-012','REFERENCE','Link authoritative stock movements without assuming complete ledger coverage.',False,refs(1,5)),('https://ref.gs1.org/standards/epcis/2.0.1/','ALIGN','Candidate event-evidence alignment with explicit quantity and time mapping losses; not conformance.',False,refs(6)),('https://www.w3.org/TR/prov-dm/','ALIGN','Describe attribution and derivation, not permissions or physical truth.',False,refs(9))]]
    omissions=['Claude and Grok each timed out once. No independent external review; Codex-only result must remain reviewable-draft.','Mutable Microsoft page revision pins remain open; Odoo stock report inspected via indexed text only after direct fetch timeout.','GS1 URL says 2.0.1 while retrieved PDF header says Release 2.0 June 2022; exact normative adapter pin and conformance remain unresolved.','Nested field groups are proposed information contracts, not executable instance schemas; no inventory engine, reservation adapter or concurrency test delivered.','Sector-specific unit conversion, negative-stock, quarantine, consignment and retention profiles need specialist review.','Actual master authority, expected-version and idempotency capabilities must be verified by adopters; source API inspection did not establish these guarantees.']
    dims=[('identity','Issuer and complete stock dimension tuple.'),('classification','Source-qualified stock status and nonphysical aggregate class.'),('direct properties','Quantity, unit, precision and declared bucket semantics.'),('recognition','Source keys, dimension grain and observation evidence; not visual item recognition.'),('capabilities','Six bounded proposed information operations; execution authority external.'),('lifecycle','Snapshot correction, count application and action disposition.'),('temporal','Effective, recorded and counted time plus freshness and completeness.'),('relationships','Owner, custodian, product, location, movement and order references.'),('provenance','Snapshot, count and reconstruction evidence.'),('ownership','Goods owner, custodian and data authority distinguished.'),('validation','Reconciliation, incompatible quantities and incomplete-snapshot fixtures proposed.'),('access','Role and owner-scoped disclosure.'),('retention','Policy-controlled preservation, correction and tombstones.'),('interoperability','Source measure mapping with positive-only event quantity limitation.')]
    coverage=dict(claim='Proposed source-grounded stock-position contract with explicit runtime and review limitations, not exhaustive warehouse coverage or a transactional inventory system.',confidence='medium',checklist=[dict(dimension=d,status='covered',notes=n) for d,n in dims]+[dict(dimension='Physical geometry and material',status='not-applicable',notes='A quantity position is informational; actual item characteristics remain referenced.'),dict(dimension='Executable conformance',status='gap',notes='Nested schemas, adapters, real fixtures and independent external review deferred.')],known_omissions=omissions,conflicts=[],regional_assumptions=['Owning Dimension supplies jurisdiction, warehouse, confidentiality and retention policies. No legal ownership or financial valuation determination is made.'],adversarial_checks=['Reject owner and custodian conflation.','Reject sums across overlapping buckets or reservation hierarchy grains.','Reject absent row, stale value or omitted quantity interpreted as zero.','Reject expected-receipt reservation as physical stock.','Reject a count applied without intervening movement reconciliation.','Reject signed or zero stock blindly exported as positive EPCIS QuantityElement.','Reject local edit treated as execution and uncertain-action blind retries.'])
    return dict(schema_version='1.0.0',model=model,sources=sources,structure=dict(bundles=bundles),functions=functions,composition=composition,service_layers=services,coverage=coverage)

if __name__=='__main__':
    (RUN/'codex.result.json').write_text(json.dumps(build(),ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
